#!/bin/bash
git worktree list --porcelain | awk '/^worktree/{p=$2} /^HEAD/{h=$2} /^branch/{b=$2} /^locked/{l=1} /^$/{print p, h, b, l; l=""; b=""}' | grep '/worktrees/agent-' | grep -v -E 'ab3d7d44|ac67dbdb|a815b711|ae0dc22a|af286df1|/target/' | while read p h b l; do
 [ -n "$l" ] && { echo "LOCKED ${p##*/}"; continue; }
 st=$(git -C $p status --porcelain 2>&1 | grep -v ' target/$' | head -3 | tr '\n' ';')
 anc=no; git merge-base --is-ancestor $h origin/main && anc=yes
 br=${b#refs/heads/}
 pr=""
 [ -n "$br" ] && pr=$(gh pr list --state all --head "$br" --json state,number -q '.[]|"#\(.number)\(.state)"' 2>/dev/null | tr '\n' ',')
 echo "${p##*/} anc=$anc br=$br pr=$pr st=[$st]"
done

